    "sub0101": {
      "title": "인사말",
      "topImage": "img_up/shop_pds/sejongcook/farm/b35391732d8e9405142f92d7b4e6037d_water__c1_w700_h170.png",
      "htmlContent": "\n        <div style=\"text-align:center; margin-bottom:20px;\">\n           <img src=\"img_up/shop_pds/sejongcook/farm/main011590398100.png\" style=\"max-width:100%; border-radius:8px;\">\n        </div>\n        <div style=\"font-family:'Noto Sans KR', sans-serif;\">\n            <p style=\"padding:15px 0; text-align:center;\">\n                <strong style=\"font-size:20px;\">\n                    <span style=\"color:#ff8c00;\">세종요리제과기술학원</span> 홈페이지에 오신것을 환영합니다.\n                </strong>\n            </p>\n            <p style=\"font-size:16px; line-height:1.6;\">\n                안녕하세요. <strong>세종요리제과기술학원</strong> 홈페이지를 찾아주셔서 감사합니다.<br><br>\n                본 학원은 국가 기술자격취득 및 이와 관련한 취업, 진학, 개업등을 목적으로 2000년도에 설립된 제과,제빵 및 조리 기술 전문학원입니다.<br>\n                어렵고 힘든 시기를 살고 있는 현대사회에서 학력, 나이, 성별에 구애없이 누구나가 도전하고 취득할 수 있는 자격증이야 말로 당신의 먼 미래를 가까운 현실로 바꿔 드릴수 있다고 믿고 있습니다.<br><br>\n                이에 본원의 모든 강사진과 저는 여러분 앞날의 지킴이로써 최선의 노력을 기울일 것이며, 또한 목표한 바 이루시도록 이끌어 나아 갈 것입니다.<br><br>\n                감사합니다.\n            </p>\n        </div>\n      ",
      "boardConfig": {
        "enable": true,
        "title": "학원소개 문의",
        "count": 5,
        "code": "qna_sub0101"
      },
      "items": []
    },
    "index": {
      "title": "홈페이지",
      "topImage": "",
      "htmlContent": "\n  <div style=\"font-family: 'Noto Sans KR', sans-serif; padding: 20px;\">\n                <h3 style=\"color: #ff8c00; border-bottom: 2px solid #ddd; padding-bottom: 10px;\">📢 홈페이지 진행중 내용 (예시)</h3>\n                \n                <p style=\"margin: 20px 0; font-size: 16px; line-height: 1.6;\">\n                    안녕하세요! 현재 <strong>세종요리제과기술학원</strong> 홈페이지가 새롭게 리뉴얼 진행 중입니다.<br>\n                    더 나은 서비스와 편리한 이용을 위해 최선을 다하고 있습니다.<br>\n                    <span style=\"color: #666;\">(이 내용은 관리자 모드에서 언제든지 수정할 수 있습니다.)</span>\n                </p>\n\n                <div style=\"margin: 20px 0; text-align: center;\">\n                    <img src=\"img_up/shop_pds/sejongcook/farm/main011590397968.png\" style=\"max-width: 100%; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.1);\" alt=\"진행 이미지\">\n                    <p style=\"font-size: 13px; color: #888; margin-top: 5px;\">▲ 요리 실습 현장</p>\n                </div>\n\n                <div style=\"background: #f9f9f9; padding: 15px; border-left: 4px solid #2ecc71; margin: 20px 0;\">\n                    <strong>✨ 주요 변경 사항</strong>\n                    <ul style=\"list-style: disc; margin-left: 20px; margin-top: 10px;\">\n                        <li>모바일/PC 반응형 디자인 적용</li>\n                        <li>카테고리별 게시판 연동 강화</li>\n                        <li>빠른 수강 상담 기능 추가</li>\n                    </ul>\n                </div>\n\n                <table style=\"width: 100%; border-collapse: collapse; margin-top: 20px;\">\n                    <thead>\n                        <tr style=\"background: #333; color: #fff;\">\n                            <th style=\"padding: 10px; border: 1px solid #ddd;\">구분</th>\n                            <th style=\"padding: 10px; border: 1px solid #ddd;\">내용</th>\n                            <th style=\"padding: 10px; border: 1px solid #ddd;\">비고</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">위치</td>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">메인 페이지</td>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">-</td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">작업 상태</td>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">진행 중</td>\n                            <td style=\"padding: 10px; border: 1px solid #ddd; text-align: center;\">2026.01.11</td>\n                        </tr>\n                    </tbody>\n                </table>\n\n                <div style=\"margin-top: 30px; text-align: center;\">\n                    <a href=\"page/sub0201.html\" style=\"background: #f5a623; color: #fff; padding: 10px 20px; text-decoration: none; border-radius: 5px; font-weight: bold;\">\n                        👉 제과제빵 교육과정 보러가기\n                    </a>\n                </div>\n            </div>\n        "
    },
