      "htmlContent": "\n    <div style=\"font-family:'Noto Sans KR', sans-serif;\">\n            <div class='map_381171_' style=\"margin-bottom:20px;\">\n                <iframe src='../세종요리제과기술학원 오시는 길_files/kakao_map_xy_load.html' width='100%' height='450' frameborder='0' scrolling='no' id='kakao_map_dynamic' style=\"border-radius:8px; border:1px solid #ddd;\"></iframe>\n            </div>\n            \n            <h3 style=\"color:#2c3e50; border-bottom:2px solid #34495e; padding-bottom:10px;\">📍 오시는 길 (Location)</h3>\n            \n            <div style=\"display:flex; flex-direction:column; gap:15px; margin-top:20px;\">\n                <div style=\"background:#f9f9f9; padding:15px; border-radius:8px;\">\n                    <strong style=\"color:#e67e22; font-size:18px;\">🏢 주소</strong>\n                    <p style=\"margin-top:5px; font-size:16px;\">경기 김포시 김포대로 841 제우스 프라자 6층 <br><span style=\"color:#7f8c8d; font-size:14px;\">(사우역 3번 출구 도보 1분)</span></p>\n                </div>\n\n                <div style=\"background:#f9f9f9; padding:15px; border-radius:8px;\">\n                    <strong style=\"color:#e67e22; font-size:18px;\">📞 연락처</strong>\n                    <p style=\"margin-top:5px; font-size:16px;\">031-983-1933</p>\n                </div>\n            </div>\n        </div >\n  ",
